@section('script')
<script>
const mediaStore=@json(route('user.humas.media-contacts.store',['userId'=>$userId]));
const mediaUpdate=@json(route('user.humas.media-contacts.update',['userId'=>$userId,'id'=>'__ID__']));
function openMediaCreate(){document.getElementById('mediaTitle').textContent='Tambah Kontak';document.getElementById('mediaForm').action=mediaStore;document.getElementById('mediaMethod').value='POST';['mediaName','mediaInstitution','mediaPerson','mediaPhone','mediaEmail','mediaAddress','mediaNotes'].forEach(id=>document.getElementById(id).value='');document.getElementById('mediaType').value='media';document.getElementById('mediaActive').checked=true;}
function openMediaEdit(btn){const d=JSON.parse(btn.dataset.contact);document.getElementById('mediaTitle').textContent='Edit Kontak';document.getElementById('mediaForm').action=mediaUpdate.replace('__ID__',d.id);document.getElementById('mediaMethod').value='PUT';document.getElementById('mediaName').value=d.name||'';document.getElementById('mediaType').value=d.type||'media';document.getElementById('mediaInstitution').value=d.institution||'';document.getElementById('mediaPerson').value=d.contact_person||'';document.getElementById('mediaPhone').value=d.phone||'';document.getElementById('mediaEmail').value=d.email||'';document.getElementById('mediaAddress').value=d.address||'';document.getElementById('mediaNotes').value=d.notes||'';document.getElementById('mediaActive').checked=!!d.is_active;new bootstrap.Modal(document.getElementById('mediaModal')).show();}
</script>
